// Level recipes for Adventure mode. Layout + goals are defined here
// procedurally; move limits and star thresholds come from level-tuning.js,
// which is generated by `npm run balance` (a bot plays every level many
// times and picks values that hit a target difficulty curve).

import { Rng } from './rng.js';
import { TUNING } from './level-tuning.js';

// Levels 1-60 are individually bot-tuned. Beyond that the reef never ends:
// endless levels remix the bot-tuned late-game layouts (see getLevel).
export const LEVEL_COUNT = 60;
export const MAX_LEVEL = 99999;
const REMIX_FROM = 31; // levels 31..60 are the remix pool
const REMIX_SPAN = LEVEL_COUNT - REMIX_FROM + 1; // 30

export const WORLDS = [
  { name: 'Sunny Shallows', bg: ['#7fd4f5', '#2a8fd6'] },
  { name: 'Coral Gardens', bg: ['#ff9eb5', '#7b5fd6'] },
  { name: 'Kelp Forest', bg: ['#7be0a8', '#1f7a6a'] },
  { name: 'Shipwreck Bay', bg: ['#f5c77f', '#8a5a3a'] },
  { name: 'Moonlit Lagoon', bg: ['#8fa8ff', '#2b2f7a'] },
  { name: 'Abyss Trench', bg: ['#5a7bd6', '#0d1638'] },
];

const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];

/** World info for any level number (worlds repeat with a numeral: "Coral Gardens II"). */
/** Difficulty label from the same win-rate curve the balancer targets. */
export function difficultyOf(n) {
  const inWorld = (n - 1) % 10;
  let w = 0.97 - 0.0045 * Math.min(n, 60) - 0.012 * inWorld;
  if (n % 10 === 0) w -= 0.16;
  return n % 10 === 0 && n >= 20 ? 'super' : w < 0.72 ? 'hard' : null;
}

export function worldOf(n) {
  const w = Math.floor((n - 1) / 10);
  const base = WORLDS[w % WORLDS.length];
  const lap = Math.floor(w / WORLDS.length) + 1;
  const numeral = lap <= 10 ? ROMAN[lap] : String(lap);
  return { index: w, name: lap > 1 ? `${base.name} ${numeral}` : base.name, bg: base.bg, boss: n % 10 === 0 };
}

export const CREATURES = ['Crab', 'Starfish', 'Urchin', 'Turtle', 'Jelly', 'Snail'];

const HOLE_PATTERNS = [
  () => [],
  (n) => [[0, 0], [0, n - 1], [n - 1, 0], [n - 1, n - 1]],
  (n) => { const m = Math.floor(n / 2); return [[m, m]]; },
  (n) => [[0, 0], [0, 1], [1, 0], [0, n - 1], [0, n - 2], [1, n - 1]],
  (n) => { const m = Math.floor(n / 2); return [[m - 1, 0], [m, 0], [m + 1, 0], [m - 1, n - 1], [m, n - 1], [m + 1, n - 1]]; },
  (n) => { const m = Math.floor(n / 2); return [[0, m], [n - 1, m]]; },
];

function jellyPattern(kind, n, rng, layers) {
  const cells = [];
  const m = Math.floor(n / 2);
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++) {
      let on = false;
      switch (kind) {
        case 'center': on = Math.abs(r - m) <= 1 && Math.abs(c - m) <= 1; break;
        case 'bottom': on = r >= n - 2; break;
        case 'cross': on = r === m || c === m; break;
        case 'border': on = r === 0 || c === 0 || r === n - 1 || c === n - 1; break;
        case 'diag': on = r === c || r + c === n - 1; break;
        case 'checker': on = (r + c) % 2 === 0 && r >= 2; break;
        case 'full': on = true; break;
        default: on = rng.next() < 0.35;
      }
      if (on) cells.push([r, c, layers]);
    }
  return cells;
}

function cratePattern(kind, n, hp) {
  const cells = [];
  const m = Math.floor(n / 2);
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++) {
      let on = false;
      switch (kind) {
        // full-width walls would cut the board off from the sky: leave a gap every third column
        case 'row': on = (r === m || r === m + 2) && c % 3 !== 1; break;
        case 'top': on = r <= 1 && c % 3 !== 1; break;
        case 'ring': on = Math.max(Math.abs(r - m), Math.abs(c - m)) === 2; break;
        case 'pillars': on = (c === 1 || c === n - 2) && r >= 2 && r <= n - 3; break;
        case 'corners': on = (r < 2 || r >= n - 2) && (c < 2 || c >= n - 2); break;
        case 'center': on = Math.abs(r - m) <= 1 && Math.abs(c - m) <= 1; break;
      }
      if (on) cells.push([r, c, hp]);
    }
  return cells;
}

/** Tide levels from 12 on (every third level, never a boss): a wave every 5 moves, 4 later on. */
export function tideOf(n) {
  if (n < 9 || n % 10 === 0 || n % 3 !== 0) return 0;
  return n >= 40 ? 4 : 5;
}

/** The static part of a level: layout + objective kinds. */
export function levelRecipe(n) {
  const rng = new Rng(n * 7919 + 13);
  const world = Math.min(WORLDS.length - 1, Math.floor((n - 1) / 10));
  const boss = n % 10 === 0;
  const size = n <= 8 ? 8 : 9;
  // 4 colours only for the first three (tutorial) levels – after that, fewer free cascades so choices matter
  const colors = n <= 3 ? 4 : n <= 24 ? 5 : boss || n > 45 ? 6 : 5;
  const recipe = { n, world, boss, rows: size, cols: size, colors, holes: [], jelly: [], crates: [], goals: [] };

  if (n > 8) recipe.holes = HOLE_PATTERNS[n % HOLE_PATTERNS.length](size);
  else if (n === 2) recipe.holes = HOLE_PATTERNS[1](size);
  else if (n === 3) recipe.holes = HOLE_PATTERNS[5](size);
  else if (n === 5) recipe.holes = HOLE_PATTERNS[3](size);

  // Teach goals gradually, then mix them.
  let kinds;
  if (n <= 3) kinds = ['score'];
  else if (n <= 5) kinds = ['collect'];
  else if (n <= 8) kinds = ['jelly'];
  else if (n <= 10) kinds = ['jelly', 'collect'];
  else if (n <= 13) kinds = ['crate'];
  else {
    const options = [['score'], ['collect'], ['jelly'], ['crate'], ['jelly', 'collect'], ['crate', 'collect'], ['crate', 'jelly']];
    kinds = boss ? ['crate', 'jelly'] : options[(n * 5 + world) % options.length];
  }

  const crateKinds = ['row', 'top', 'ring', 'pillars', 'corners', 'center'];
  const holeSet = new Set(recipe.holes.map(([r, c]) => r * 64 + c));
  const free = ([r, c]) => !holeSet.has(r * 64 + c);

  const jellyPick = n <= 6 ? 'center' : ['center', 'bottom', 'cross', 'border', 'diag', 'checker', 'random'][(n + world) % 7];
  // six colours make matching much harder – only on single-goal levels
  if (recipe.colors === 6 && (kinds.length > 1 || jellyPick === 'border')) recipe.colors = 5;

  for (const k of kinds) {
    if (k === 'jelly') {
      const pattern = jellyPick;
      const layers = n >= 14 && kinds.length === 1 && ['center', 'cross', 'diag', 'bottom'].includes(pattern) && rng.next() < 0.6 ? 2 : 1;
      recipe.jelly = jellyPattern(pattern, size, rng, layers).filter(free);
      recipe.goals.push({ type: 'jelly' });
    } else if (k === 'crate') {
      const hp = n >= 12 && rng.next() < (kinds.includes('jelly') ? 0.35 : 0.65) ? 2 : 1;
      const jellySet = new Set(recipe.jelly.map(([r, c]) => r * 64 + c));
      recipe.crates = cratePattern(crateKinds[(n * 3) % crateKinds.length], size, hp).filter(
        (p) => free(p) && !jellySet.has(p[0] * 64 + p[1]),
      );
      // every crate row needs a real gap to the sky: if the gaps land on holes, open one crate
      const holeAt = new Set(recipe.holes.map(([r, c]) => r * 64 + c));
      const rowsWithCrates = [...new Set(recipe.crates.map((p) => p[0]))];
      for (const r of rowsWithCrates) {
        const inRow = recipe.crates.filter((p) => p[0] === r);
        const openCells = Array.from({ length: size }, (_, c) => c).filter((c) => !holeAt.has(r * 64 + c) && !inRow.some((p) => p[1] === c));
        if (inRow.length >= size - 2 && !openCells.length) {
          const mid = inRow.slice().sort((a, b) => Math.abs(a[1] - size / 2) - Math.abs(b[1] - size / 2))[0];
          recipe.crates = recipe.crates.filter((p) => p !== mid);
        }
      }
      recipe.goals.push({ type: 'crate' });
    } else if (k === 'collect') {
      const howMany = n <= 5 ? 1 : n < 30 ? 2 : 3;
      const picks = rng.shuffle([...Array(recipe.colors).keys()]).slice(0, Math.min(howMany, colors));
      for (const color of picks) recipe.goals.push({ type: 'collect', color, count: 0 });
    } else {
      recipe.goals.push({ type: 'score', target: 0 });
    }
  }
  return recipe;
}

/** Full playable config for level n (seed decides the random gem fall). */
export function getLevel(n, seed) {
  if (n > LEVEL_COUNT) return remixLevel(n, seed);
  const recipe = levelRecipe(n);
  const t = TUNING[n] || defaultTuning(recipe);
  const objectives = recipe.goals.map((g) => {
    if (g.type === 'collect') return { ...g, count: t.collect };
    if (g.type === 'score') return { ...g, target: t.target };
    return { ...g };
  });
  return {
    level: n,
    world: recipe.world,
    boss: recipe.boss,
    mode: 'level',
    rows: recipe.rows,
    cols: recipe.cols,
    colors: recipe.colors,
    holes: recipe.holes,
    jelly: recipe.jelly,
    crates: recipe.crates,
    // Tide levels: every few moves a wave sweeps the bottom row (and fires any specials in it)
    ...(tideOf(n) ? { tideEvery: tideOf(n) } : {}),
    moves: t.moves,
    stars: t.stars,
    objectives,
    seed: seed >>> 0,
  };
}

/** Endless levels (61+): a bot-tuned late-game layout, mirrored on odd laps,
 * with its goal creatures re-coloured and a slightly tighter move limit on
 * each lap (capped, so it stays winnable). Boss levels stay on every 10th. */
function remixLevel(n, seed) {
  const k = n - LEVEL_COUNT - 1;
  const lap = Math.floor(k / REMIX_SPAN) + 1;
  const base = getLevel(REMIX_FROM + (k % REMIX_SPAN), seed);
  const rng = new Rng(n * 104729 + 7);
  const mirror = lap % 2 === 1;
  const flip = ([r, c, ...rest]) => [r, mirror ? base.cols - 1 - c : c, ...rest];
  const perm = rng.shuffle([...Array(base.colors).keys()]);
  // up to 9% fewer moves; collect goals are move-sensitive, so they keep theirs
  const squeeze = base.objectives.some((o) => o.type === 'collect') ? 1 : 1 - 0.03 * Math.min(lap, 3);
  const moves = Math.max(10, Math.round(base.moves * squeeze));
  const ratio = moves / base.moves;
  const round500 = (x) => Math.max(500, Math.round(x / 500) * 500);
  const objectives = base.objectives.map((o) => {
    if (o.type === 'collect') return { ...o, color: perm[o.color] };
    if (o.type === 'score') return { ...o, target: round500(o.target * ratio) };
    return { ...o };
  });
  const stars = base.stars.map((x) => round500(x * ratio));
  if (stars[1] <= stars[0]) stars[1] = stars[0] + 500;
  if (stars[2] <= stars[1]) stars[2] = stars[1] + 1000;
  const w = worldOf(n);
  return {
    ...base,
    level: n,
    world: w.index,
    boss: w.boss,
    holes: base.holes.map(flip),
    jelly: base.jelly.map(flip),
    crates: base.crates.map(flip),
    moves,
    stars,
    objectives,
  };
}

export function defaultTuning(recipe) {
  const moves = 20 + Math.floor(recipe.n / 6);
  return { moves, collect: 12 + recipe.n, target: 3000 + recipe.n * 300, stars: [1000, 4000, 8000] };
}
